class Solution { public: vector<int> maximumBeauty(vector<vector<int>>& items,vector<int>& queries){sort(items.begin(),items.end());for(int i=1;i<(int)items.size();++i)items[i][1]=max(items[i][1],items[i-1][1]);vector<int> answer;for(int query:queries){int left=0,right=items.size();while(left<right){int middle=(left+right)/2;if(items[middle][0]<=query)left=middle+1;else right=middle;}answer.push_back(left?items[left-1][1]:0);}return answer;} };
